@Component("dSP-entity-projector")
public class DSPEntityProjector implements EntityProjector<DSP>{
		
	// core constructor
	public DSPEntityProjector(ProjectorRegistry registry,
										DSPRepository repository ) {
        this.registry 	= registry;
		this.repository = repository;
    }

	@Override
	public Class<DSP> getEntityClass() {
		return DSP.class;
	}

    /*
	 * Insert a DSP
	 * 
     * @param	entity DSP
     */
    public DSP create( DSP entity) {
	    LOGGER.info("creating " + entity.toString() );
	   
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    return repository.save(entity);
        
    }

	/*
	 * Update a DSP
	 * 
     * @param	entity DSP
     */
    public DSP update( DSP entity) {
	    LOGGER.info("updating " + entity.toString() );

	    // ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		return repository.save(entity);

    }
    
	/*
	 * Delete a DSP
	 * 
     * @param	id		UUID
     */
    public DSP delete( UUID id ) {
	    LOGGER.info("deleting " + id.toString() );

    	// ------------------------------------------
    	// locate the entity by the provided id
    	// ------------------------------------------
	    DSP entity = repository.findById(id).get();
	    
    	// ------------------------------------------
    	// delete what is discovered 
    	// ------------------------------------------
    	repository.delete( entity );
    	
    	return entity;
    }    


    /*
     * Add to the AdAccounts
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	DSP
     */
    public DSP addToAdAccounts( UUID parentId, AdAccount addTo ) {
	    LOGGER.info("handling AssignAdAccountsToDSPEvent - " );
	    
	    DSP parentEntity = repository.findById(parentId).get();
	    AdAccount child = registry.project( AdAccount.class, addTo.getAdAccountId());
	    
	    parentEntity.getAdAccounts().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the AdAccounts
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	DSP
     */
	public DSP removeFromAdAccounts( UUID parentId, AdAccount removeFrom ) {
	    LOGGER.info("handling RemoveAdAccountsFromDSPEvent " );
	
	    DSP parentEntity = repository.findById(parentId).get();
	    AdAccount child = registry.project( AdAccount.class, removeFrom.getAdAccountId());
	    
	    parentEntity.getAdAccounts().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



    /**
     * Method to retrieve the DSP via an FindDSPQuery
     * @return 	query	FindDSPQuery
     */
    @SuppressWarnings("unused")
    public DSP find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a DSP - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all DSPs
     *
     * @param	query	FindAllDSPQuery 
     * @return 	List<DSP> 
     */
    @SuppressWarnings("unused")
    public List<DSP> findAll( FindAllDSPQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all DSP - {0}", exc.getMessage() );
    	}
    	return null;
    }


    //--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
    protected final DSPRepository repository;
	protected final ProjectorRegistry registry;


    private static final Logger LOGGER 	= LoggerFactory.getLogger(DSPEntityProjector.class.getName());

}
